{
  "$schema": "https://opencode.ai/config.json",
  "shell": "powershell",
  "enabled_providers": [
    "ollama"
  ],
  "plugins": [
    "opencode-ollama-toolcall-proxy"
  ],
  "model": "ollama/gemma4:12b",
  "default_agent": "build",
  "snapshots": true,
  "formatter": true,
  "tool_output": {
    "max_lines": 5000,
    "max_bytes": 200000
  },
  "compaction": {
    "auto": true,
    "buffer": 4000
  },
  "agents": {
    "build": {
      "description": "Primary hands-on coding agent",
      "mode": "primary",
      "system": "You are a genius software developer with a PhD in Computer Science. You are very hands-on and modifying files, always working. You have the following tools available: write, shell, webfetch, glob, patch, grep, read, edit. CRITICAL: When you decide to use a tool, you MUST invoke it IMMEDIATELY. Do NOT describe what you are about to do. Do NOT say 'Let me...' or 'I will...' — just CALL THE TOOL RIGHT NOW. Never stop after declaring intent; always execute the tool. The default shell is bash, so use bash/Linux commands. We run Windows 11. Prefer making minimal, focused changes. Always consider edge cases and write clean, maintainable code.\n\nFIRST: At the start of every task, check whether AGENTS.md and TODO.md exist in the project root. If either is missing, search the conversation for the latest planning output wrapped in <!-- AGENTS.md --> / <!-- /AGENTS.md --> and <!-- TODO.md --> / <!-- /TODO.md -->. If found, write those files first before doing any other work. If no plan block is present, proceed without creating them.\n\nBEFORE EDITING A FILE: always re-read it with the read tool to get the exact current content, then copy that text exactly (including indentation, whitespace, and line endings) into the old_string of the edit tool. If the file may have changed since you last read it, re-read it again. For multi-line or complex changes, prefer the patch tool.",
      "steps": 100
    },
    "plan": {
      "description": "Read-only architect that prepares AGENTS.md and TODO.md content",
      "mode": "all",
      "system": "You are a senior software architect. Your job is to plan work by preparing the full content of two files. You are in read-only planning mode, so do NOT write files.\n\n1. AGENTS.md — high-level architecture, decisions, constraints, and conventions for this codebase.\n2. TODO.md — a concrete, ordered task list with checkboxes for the current goal.\n\nDo NOT ask the user clarifying questions. Make reasonable, standard assumptions and produce the plan immediately. Read existing AGENTS.md and TODO.md (if they exist), then output the proposed content for BOTH files using these exact markers:\n\n<!-- AGENTS.md -->\n...content...\n<!-- /AGENTS.md -->\n\n<!-- TODO.md -->\n...content...\n<!-- /TODO.md -->\n\nDo NOT use the built-in todowrite tool. Write clear, LLM-readable markdown. Break complex problems into clear, actionable steps. Consider trade-offs in performance, maintainability, and scalability. The default shell is bash, so prefer bash/Linux style commands. We run Windows 11. Be concise but thorough.",
      "permissions": [
        {
          "action": "edit",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "shell",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "webfetch",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "websearch",
          "resource": "*",
          "effect": "deny"
        },
        {
          "action": "subagent",
          "resource": "*",
          "effect": "deny"
        }
      ],
      "steps": 100
    },
    "explore": {
      "description": "Codebase explorer — 40K context for large projects",
      "mode": "subagent",
      "system": "You are a codebase explorer. Find relevant files, understand project structure, and provide concise summaries. Use grep and glob to search efficiently. The default shell is bash, so prefer bash/Linux style commands. We run Windows 11. Focus on finding the right files, not writing code.",
      "steps": 100
    },
    "title": {
      "description": "Generates concise conversation titles",
      "hidden": true,
      "model": "ollama/gemma4:12b",
      "steps": 100
    },
    "summary": {
      "description": "Summarizes long conversations and contexts",
      "hidden": true,
      "steps": 100
    },
    "compaction": {
      "description": "Compresses conversation context when limits are reached",
      "hidden": true,
      "steps": 100
    }
  },
  "commands": {
    "refactor": {
      "template": "Refactor the following code to improve readability, performance, and maintainability. Preserve all existing behavior and add comments explaining complex logic:\n\n{{input}}",
      "description": "Refactor selected code",
      "agent": "build"
    },
    "test": {
      "template": "Write comprehensive unit tests for the following code. Include edge cases, error conditions, and mocking where appropriate:\n\n{{input}}",
      "description": "Generate unit tests",
      "agent": "build"
    },
    "debug": {
      "template": "Debug the following code. Identify the root cause of any issues, explain your reasoning, and provide a corrected version:\n\n{{input}}",
      "description": "Debug code issues",
      "agent": "build"
    },
    "reason": {
      "template": "Think through this problem step by step. Consider all edge cases, constraints, and possible solutions before giving a final answer:\n\n{{input}}",
      "description": "Deep reasoning mode (slower but thorough)",
      "subagent": true
    },
    "plan": {
      "template": "Create or update AGENTS.md and TODO.md for the following goal. Read existing files first if they exist:\n\n$ARGUMENTS",
      "description": "Plan a task by writing AGENTS.md and TODO.md",
      "agent": "plan"
    }
  },
  "providers": {
    "ollama": {
      "name": "Ollama (local)",
      "package": "aisdk:@ai-sdk/openai-compatible",
      "settings": {
        "baseURL": "http://localhost:11434/v1",
        "headerTimeout": 600000
      },
      "models": {
        "gemma4:12b": {
          "name": "Gemma 4 12B (Google, 12B params)",
          "capabilities": {
            "tools": true,
            "reasoning": {
              "supported": false
            }
          },
          "body": {
            "max_tokens": 16384
          }
        },
        "laguna-xs-2.1:latest": {
          "name": "Laguna XS 2.1 (local, 20 GB)",
          "capabilities": {
            "tools": true,
            "reasoning": {
              "supported": false
            }
          },
          "body": {
            "max_tokens": 16384
          }
        },
        "qwen3.5:9b": {
          "name": "Qwen3.5 9B (Alibaba, 9B params)",
          "capabilities": {
            "tools": true,
            "reasoning": {
              "supported": false
            }
          },
          "body": {
            "max_tokens": 16384
          }
        },
        "qwen3.5:9b-32k": {
          "name": "Qwen3.5 9B 32K context",
          "capabilities": {
            "tools": true,
            "reasoning": {
              "supported": false
            }
          },
          "body": {
            "max_tokens": 16384
          }
        },
        "ornith:35b": {
          "name": "Ornith 35B (Qwen3.5 MoE, tool-calling)",
          "capabilities": {
            "tools": true,
            "reasoning": {
              "supported": true
            }
          },
          "body": {
            "max_tokens": 16384
          }
        }
      }
    }
  }
}

{
  "name": "opencode-ollama-toolcall-proxy",
  "version": "0.3.0",
  "description": "OpenCode plugin (V1 + V2) that converts raw tool-call markup from local Ollama models into standard OpenAI tool_calls, plus line-ending normalization for file edits.",
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "opencode.example.json"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "esbuild index.ts --bundle --platform=node --format=esm --outfile=dist/index.js --external:@opencode/plugin --external:@opencode-ai/plugin --external:editorconfig",
    "test": "node --experimental-strip-types test.ts",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ollama",
    "tool-calling",
    "function-calling",
    "local-llm",
    "line-endings"
  ],
  "author": "",
  "license": "MIT",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.19.4",
    "@types/node": "^22.0.0",
    "esbuild": "^0.25.0",
    "typescript": "^5.0.0"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.0",
    "editorconfig": "^3.0.2"
  }
}
